import {createSimpleUI} from './simple-ui.js';
import {STAGES,HEALTH,KINDS,ISSUE_STATES,person,project,done,taskStatus,activeIssue,tasksFor,issuesFor,projectMetrics,reportRows,reportProjects} from './model.js';
let s,ui={page:'mywork',person:localStorage.getItem('autopm-person')||'sun',mode:localStorage.getItem('autopm-mode')||'contributor',personalTab:'today',search:'',health:'',stage:'',projectTab:'overview',supportTab:'issues',supportStatus:'open',severity:'',department:'',reportProjectIds:[],reportProgram:'',reportDepartment:'',reportHealth:'',projectId:'',programId:'',dept:'NPI',deptTab:'overview'},currentDrawer=null,saving=false;
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={work:'M4 6h16v14H4z M9 6V3h6v3 M4 11h16 M10 11v3h4v-3',projects:'M3 6h6l2 3h10v12H3z',portfolio:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',reports:'M4 3h16v18H4z M8 16v-4 M12 16V8 M16 16v-6',support:'M12 3 2 21h20z M12 9v5 M12 17v1',department:'M8 3h8v18H8z M2 10h6v11H2z M16 10h6v11h-6z M11 7h2 M11 11h2 M11 15h2',arrow:'m9 5 7 7-7 7',plus:'M12 4v16 M4 12h16',search:'M21 21l-6-6 M17 9a8 8 0 1 1-16 0 8 8 0 0 1 16 0',help:'M12 16v1 M9 8a3 3 0 1 1 4 3l-1 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',x:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',menu:'M4 6h16 M4 12h16 M4 18h16'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[n]||icons.work}"/></svg>`;
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
const button=(label,action,id='',cls='',ico='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}" ${!label?`aria-label="${action==='menu'?'Open navigation':'Close'}"`:''}>${ico?icon(ico):''}${esc(label)}</button>`;
const editAllowed=()=>ui.mode!=='viewer';
const badge=(value)=>{let color=/Complete|Approved|Pass|On Track|Closed|Done|No Further|In MP/.test(value)?'green':/Overdue|Delayed|Critical|Fail/.test(value)?'red':/Risk|High|Needs|Returned|Conditional/.test(value)?'amber':/Review|Progress|Recovery|Development/.test(value)?'blue':/Assessment/.test(value)?'purple':'';return `<span class="pill ${color}">${esc(value||'Not set')}</span>`;};
const options=(items,selected,empty)=>`${empty!==undefined?`<option value="">${esc(empty)}</option>`:''}${items.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${Array.isArray(selected)?selected.includes(v)?'selected':'':selected===v?'selected':''}>${esc(l)}</option>`;}).join('')}`;
const depts=()=>[...new Set(s.people.map(x=>x.department))];
const date=v=>v?new Date(v+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'Not set';
const name=id=>person(s,id)?.name||'Unassigned';
const pName=id=>project(s,id)?.name||'Project';
const field=(label,name,value,type='text',hint='')=>`<div class="field"><label for="f-${name}">${esc(label)}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}">${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}">`}${hint?`<span class="hint">${esc(hint)}</span>`:''}</div>`;
const selectField=(label,key,items,value,multiple=false,hint='')=>`<div class="field"><label for="f-${key}">${esc(label)}</label><select id="f-${key}" name="${key}" ${multiple?'multiple':''}>${options(items,value)}</select>${hint?`<span class="hint">${esc(hint)}</span>`:''}</div>`;
const checks=(label,key,items,values)=>`<div class="field"><label>${esc(label)}</label><div class="check-options">${items.length>15?`<input type="search" class="check-search" aria-label="Search ${esc(label)}" placeholder="Search ${esc(label)}">`:""}${items.map(([id,label])=>`<label><input type="checkbox" name="${key}" value="${esc(id)}" ${values.includes(id)?'checked':''}>${esc(label)}</label>`).join('')}</div></div>`;
const empty=t=>`<div class="empty">${esc(t)}</div>`;
const stat=(label,value,sub,cls='')=>`<div class="stat ${cls}"><small>${esc(label)}</small><div class="value">${esc(value)}</div><small>${esc(sub)}</small></div>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2>${action}</div>${body}</section>`;
const tabs=(list,current,action)=>`<div class="tabs">${list.map(([id,label])=>button(label,action,id,current===id?'active':'')).join('')}</div>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function errorAtForm(message){const el=$('#form-error');if(el){el.textContent=message;if(message.includes('updated elsewhere')){el.insertAdjacentHTML('beforeend',`<div style="margin-top:10px">${button('Discard draft and load latest','reload-workspace')}</div>`);}el.classList.add('show');el.scrollIntoView({block:'nearest'});}else toast(message);}
async function operation(type,id,values={}){if(saving)throw new Error('A save is already in progress.');saving=true;try{const response=await fetch('/api/operation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,id,values,actorId:ui.person,mode:ui.mode,revision:s.revision})});const data=await response.json();if(!response.ok)throw new Error(data.error||'The change could not be saved.');s=data.state;render();toast(data.label+' · saved locally');return data;}finally{saving=false;}}
function showDrawer(title,subtitle,body,{save='',wide=false}={}){currentDrawer={title,subtitle};$('#overlay').innerHTML=`<div class="overlay" data-action="backdrop"><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-head"><div class="grow"><div class="overline">${esc(subtitle)}</div><h2 id="drawer-title">${esc(title)}</h2></div>${button('','close','','quiet','x')}</header><form id="detail-form" class="drawer-body"><div id="form-error" class="form-error" role="alert"></div>${body}</form><footer class="drawer-foot">${button('Close','close')}${save&&editAllowed()?`<button type="submit" form="detail-form" class="primary">${esc(save)}</button>`:''}</footer></section></div>`;$('#overlay').querySelector('[data-action="close"]').setAttribute('aria-label','Close detail');$('#overlay').querySelector('[data-action="close"]').focus();document.body.style.overflow='hidden';if(!editAllowed())$('#detail-form').querySelectorAll('input,select,textarea').forEach(e=>e.disabled=true);}
function closeDrawer(){currentDrawer=null;$('#overlay').innerHTML='';document.body.style.overflow='';}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,50).join('')}</tbody></table>${rows.length>50?`<div class="list-footer"><button type="button" data-action="more-table" data-table="${rememberRows(rows)}">Show more rows</button><span class="small muted">50 of ${rows.length}</span></div>`:''}</div>`;}
const tableRows=new Map();let tableSeq=0;function rememberRows(rows){const id=String(++tableSeq);tableRows.set(id,{rows,shown:50});return id;}
function taskTable(ts,{showProject=true}={}){if(!ts.length)return empty('No tasks match this view. Try another person or filter.');return table(['', 'Work item',...(showProject?['Project']:[]),'Owner','Due','Status'],ts.map(t=>`<tr><td><button class="check ${done(t)?'checked':t.completedBy.includes(ui.person)?'partial':''}" data-action="confirm-task" data-id="${esc(t.id)}" aria-label="${t.completedBy.includes(ui.person)?'Undo':'Confirm'} my part: ${esc(t.title)}" ${!editAllowed()||!t.ownerIds.includes(ui.person)?'disabled':''}>${done(t)||t.completedBy.includes(ui.person)?icon('check'):''}</button></td><td class="task-title">${button(t.title,'task',t.id,'link')}<span class="sub">${esc(t.workstream)} · ${esc(t.kind)} ${t.kind==='Test'&&t.testResult!=='Not Reported'?' · '+esc(t.testResult):''}</span></td>${showProject?`<td>${button(t.projectId,'project',t.projectId,'link')}</td>`:''}<td>${esc(t.ownerIds.map(name).join(', '))}</td><td class="${!done(t)&&t.due<s.scenarioDate?'due-red':''}">${date(t.due)}</td><td>${badge(taskStatus(t,s.scenarioDate))}</td></tr>`));}
function issueCards(issues){return issues.length?issues.map(i=>`<div class="issue-mini"><div class="row">${badge(i.severity)}<span class="small muted">${esc(i.projectId)}</span></div><p>${button(i.title,'issue',i.id,'link')}</p><div class="row wrap"><span class="small muted">${esc(name(i.ownerId))} · ${date(i.due)}</span>${i.impactMP?badge('MP impact'):''}</div></div>`).join(''):empty('No open issues in this scope.');}
function header(title,subtitle,action=''){return `<div class="pagehead"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="row">${action}</div></div>`;}
function render(){if(!s)return;tableRows.clear();const titles={mywork:'My Work',projects:'Project Center',portfolio:'Portfolio',reports:'Status Reports',support:'Support & Knowledge',department:'Departments'};const active=person(s,ui.person)||s.people[0];$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="/mark.svg" alt=""><div>AutoPM<small>PROJECT WORKSPACE</small></div></div><div class="navlabel">Workspace</div><nav class="nav">${Object.entries(titles).map(([id,label])=>button(label,'nav',id,ui.page===id?'active':'',({mywork:'work',projects:'projects',portfolio:'portfolio',reports:'reports',support:'support',department:'department'})[id])).join('')}</nav><div class="sidebar-bottom">${button('How to use AutoPM','guide','','quiet','help')}${button('Demo settings','demo-settings','','quiet')}<div class="source-line">Local design workspace<br>Scenario · 14 Sep 2026</div></div></aside><div class="workspace"><header class="topbar">${button('','menu','','menu-btn quiet','menu')}<div class="breadcrumb">Workspace <span>/</span><strong>${titles[ui.page]}</strong></div><div class="topbar-right"><div class="persona"><span class="avatar">${initials(active.name)}</span>${button(active.name,'people','','quiet')}</div></div></header><div class="demo-strip"><span>Design sandbox · Sample data · Saved on this computer</span><span>${s.people.length.toLocaleString()} people · ${s.projects.length} projects · ${s.tasks.length.toLocaleString()} tasks</span></div><main class="main" id="main">${ui.page==='mywork'?renderMyWork():renderPage()}</main></div></div>`;}
function renderMyWork(){return simple.renderMyWork();}
function actionTable(actions){return actions.length?table(['Action','Project / issue','Due','Status'],actions.map(a=>{const i=s.issues.find(i=>i.id===a.issueId);return `<tr><td>${button(a.title,'action',a.id,'link')}</td><td>${button(i.projectId,'project',i.projectId,'link')}<span class="sub">${button(i.id,'issue',i.id,'link')}</span></td><td class="${a.due<s.scenarioDate&&a.status!=='Done'?'due-red':''}">${date(a.due)}</td><td>${badge(a.status)}</td></tr>`;})):empty('No outstanding recovery actions.');}
function renderPage(){return ({projects:()=>ui.projectId?renderProject():renderProjects(),portfolio:()=>ui.programId?renderProgram():renderPortfolio(),reports:renderReports,support:renderSupport,department:renderDepartment})[ui.page]();}
function searchBar(placeholder,extras=''){return `<div class="toolbar"><input id="workspace-search" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(ui.search)}">${extras}</div>`;}
function filterSelect(key,label,items,value){return `<select aria-label="${esc(label)}" data-filter="${key}">${options(items,value,label)}</select>`;}
function filteredProjects(list){return list.filter(p=>(!ui.health||p.health===ui.health)&&(!ui.stage||p.stage===ui.stage)&&(!ui.search||`${p.id} ${p.name} ${p.factory} ${name(p.leadId)}`.toLowerCase().includes(ui.search.toLowerCase())));}
function projectTable(ps){return ps.length?table(['Project','Stage','Health','Lead / factory','Tasks confirmed','Open issues','Target MP'],ps.map(p=>{const m=projectMetrics(s,p.id);return `<tr><td class="task-title">${button(p.name,'project',p.id,'link')}<span class="sub">${esc(p.id)} · ${esc(p.type)}</span></td><td>${esc(p.stage)}</td><td>${badge(p.health)}</td><td>${esc(name(p.leadId))}<span class="sub">${esc(p.factory)}</span></td><td><div class="row"><div class="progress"><span style="width:${m.total?m.done/m.total*100:0}%"></span></div><span class="small">${m.done}/${m.total}</span></div></td><td>${m.openIssues?badge(m.openIssues+' open'):badge('Clear')}</td><td>${date(p.targetMP)}</td></tr>`;})):empty('No projects match these filters. Clear the search or choose another status.');}
function renderProjects(){const ps=filteredProjects(s.projects);return header('Project Center','Keep the team, plan, decisions and project evidence together.',editAllowed()?button('New project','new-project','','primary','plus'):'')+searchBar('Search project, lead or factory',filterSelect('stage','All stages',STAGES,ui.stage)+filterSelect('health','All health',HEALTH,ui.health)+button('Clear filters','clear-project-filters'))+panel(`${ps.length} projects`,projectTable(ps));}
function renderProject(){const p=project(s,ui.projectId);if(!p){ui.projectId='';return renderProjects();}const ts=tasksFor(s,p.id),issues=issuesFor(s,p.id),m=projectMetrics(s,p.id),stage=STAGES.indexOf(p.stage);let body='';
 if(ui.projectTab==='overview')body=`<div class="two-col"><div>${panel('Project brief',`<div class="panel-body"><div class="detail-grid"><div class="datum"><label>Project lead</label><p>${esc(name(p.leadId))}</p></div><div class="datum"><label>Factory</label><p>${esc(p.factory)}</p></div><div class="datum"><label>Target MP</label><p>${date(p.targetMP)}</p></div><div class="datum"><label>Type</label><p>${esc(p.type)}</p></div><div class="datum"><label>Program</label><p>${button(s.programs.find(g=>g.id===p.programId)?.name||'Unassigned','program',p.programId,'link')}</p></div><div class="datum"><label>Priority</label><p>${badge(p.priority)}</p></div></div><h3 class="section-title">What is changing</h3><p class="text-block">${esc(p.scope)}</p><h3 class="section-title">Latest project update</h3><p class="text-block">${esc(p.summary)}</p></div>`,editAllowed()?button('Edit overview','edit-project',p.id):'')}${panel('Next work to move forward',taskTable(ts.filter(t=>!done(t)).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5),{showProject:false}),button('Full plan','project-tab','plan','link'))}</div><div>${panel('Open obstacles',issueCards(issues.filter(activeIssue)))}${panel('Stage decisions',`<div class="panel-body">${ts.filter(t=>t.kind==='Approval').map(t=>`<div class="value-line">${button(t.title,'task',t.id,'link')}<br>${badge(t.approvalStatus)} <span class="muted small">${date(t.approvalDate)}</span></div>`).join('')}</div>`)}<p class="source-line">${esc(p.source)}</p></div></div>`;
 if(ui.projectTab==='plan'){const list=ts.filter(t=>(!ui.taskKind||t.kind===ui.taskKind)&&(!ui.search||`${t.title} ${t.workstream}`.toLowerCase().includes(ui.search.toLowerCase())));body=searchBar('Search work or department',filterSelect('taskKind','All work types',KINDS,ui.taskKind||'')+(editAllowed()?button('Add task','new-task',p.id,'primary','plus'):''))+panel('Project plan',taskTable(list,{showProject:false}));}
 if(ui.projectTab==='skus')body=panel('SKU execution in this project',skuTable(s.projectSkus.filter(x=>x.projectId===p.id)));
 if(ui.projectTab==='issues')body=panel('Project issues',issueTable(issues),editAllowed()?button('Record issue','new-issue',p.id,'primary','plus'):'');
 if(ui.projectTab==='team')body=panel('Project team',table(['Person','Department','Role','Open tasks'],p.team.map(id=>{const a=person(s,id);return `<tr><td><span class="avatar">${initials(a.name)}</span> ${esc(a.name)}</td><td>${esc(a.department)}</td><td>${esc(a.role)}</td><td>${ts.filter(t=>t.ownerIds.includes(id)&&!done(t)).length}</td></tr>`;})),editAllowed()?button('Edit team','edit-project',p.id):'');
 if(ui.projectTab==='documents')body=panel('Project documents',documentTable(s.documents.filter(d=>d.projectId===p.id)),editAllowed()?button('Add reference','new-document',p.id,'primary','plus'):'');
 if(ui.projectTab==='history')body=panel('Project activity',historyView(s.history.filter(x=>x.projectId===p.id)));
 return button('← Back to projects','projects-back','','quiet back')+header(p.name,`${p.id} · ${p.type} · ${p.factory}`,badge(p.health)+button('Status report','report-project',p.id,'','reports'))+`<div class="stage-track">${STAGES.map((v,i)=>`<span class="${i===stage?'current':i<stage?'past':''}">${esc(v)}</span>`).join('')}</div><div class="stats">${stat('Tasks confirmed',`${m.done} / ${m.total}`,'Owner confirmations','green')}${stat('Overdue tasks',m.overdue,'Check the plan','red')}${stat('Open issues',m.openIssues,'Separate from completion','amber')}${stat('Active SKUs',m.skus,'Project execution scope')}</div>`+tabs([['overview','Overview'],['plan','Plan & Assessments'],['skus','SKUs'],['issues','Issues'],['team','Team'],['documents','Documents'],['history','History']],ui.projectTab,'project-tab')+body;
}
function programProjects(g){return s.projects.filter(p=>p.programId===g.id);}
function renderPortfolio(){const gs=s.programs.filter(g=>(!ui.brand||g.brand===ui.brand)&&(!ui.search||`${g.name} ${g.code} ${g.category}`.toLowerCase().includes(ui.search.toLowerCase())));return header('Portfolio','Programs → projects → SKU execution. A shared view for the whole team.')+searchBar('Search programs or product categories',filterSelect('brand','All brands',['Shark','Ninja'],ui.brand||''))+`<div class="cards">${gs.map(g=>{const ps=programProjects(g),psIds=ps.map(p=>p.id),skuCount=new Set(s.projectSkus.filter(x=>x.active&&psIds.includes(x.projectId)).map(x=>x.skuId)).size,issueCount=s.issues.filter(i=>psIds.includes(i.projectId)&&activeIssue(i)).length;return `<article class="program-card"><div class="program-cover"><span class="code">${esc(g.code)}</span>${badge(g.brand)}</div><div class="program-content"><h2>${button(g.name,'program',g.id,'link')}</h2><p class="small muted">${esc(g.category)}</p><div class="metric-line"><div><strong>${ps.length}</strong>Projects</div><div><strong>${skuCount}</strong>Unique SKUs</div><div><strong style="color:${issueCount?'var(--amber)':'var(--green)'}">${issueCount}</strong>Open issues</div></div><div class="row" style="margin-top:18px">${badge(g.status)}<span class="grow"></span>${button('Explore','program',g.id,'quiet','arrow')}</div></div></article>`;}).join('')}</div>`+(gs.length?'':empty('No programs match this search.'));}
function renderProgram(){const g=s.programs.find(g=>g.id===ui.programId);if(!g){ui.programId='';return renderPortfolio();}const ps=programProjects(g),ids=ps.map(p=>p.id),assignments=s.projectSkus.filter(x=>ids.includes(x.projectId));return button('← All programs','programs-back','','quiet back')+header(g.name,`${g.code} · ${g.brand} · ${g.category}`,badge(g.status))+`<div class="stats">${stat('Projects',ps.length,'Within this program')}${stat('Unique SKUs',new Set(assignments.filter(x=>x.active).map(x=>x.skuId)).size,'Counted once across projects')}${stat('At risk / delayed',ps.filter(p=>['At Risk','Delayed'].includes(p.health)).length,'Project health','amber')}${stat('Open issues',s.issues.filter(i=>ids.includes(i.projectId)&&activeIssue(i)).length,'Across linked projects','red')}</div>`+panel('Projects in this program',projectTable(ps))+panel('SKU execution across projects',skuTable(assignments))+panel('Issues requiring attention',issueTable(s.issues.filter(i=>ids.includes(i.projectId)&&activeIssue(i))));}
function skuTable(assignments){return assignments.length?table(['SKU / market','Project','Execution status','Effective MP date','Issues'],assignments.map(ps=>{const sku=s.skus.find(x=>x.id===ps.skuId),p=project(s,ps.projectId),issues=s.issues.filter(i=>i.affectedProjectSkuIds.includes(ps.id)&&activeIssue(i));return `<tr><td>${button(sku.name,'sku',ps.id,'link')}<span class="sub">${esc(sku.market)}</span></td><td>${button(p.id,'project',p.id,'link')}</td><td>${badge(ps.status)}</td><td>${date(ps.overrideDate||p.targetMP)}<span class="sub">${ps.overrideDate?'SKU exception':'Inherited project target'}</span></td><td>${issues.length?issues.map(i=>button(i.id,'issue',i.id,'link')).join('<br>'):'—'}</td></tr>`;})):empty('No SKUs have been added to this project.');}
function issueTable(issues){return issues.length?table(['Issue','Project','Department / lead','Severity','Status','Due'],issues.map(i=>`<tr><td class="task-title">${button(i.title,'issue',i.id,'link')}<span class="sub">${esc(i.id)}${i.impactMP?' · Impacts MP':''}</span></td><td>${button(i.projectId,'project',i.projectId,'link')}</td><td>${esc(i.department)}<span class="sub">${esc(name(i.ownerId))}</span></td><td>${badge(i.severity)}</td><td>${badge(i.status)}</td><td class="${activeIssue(i)&&i.due<s.scenarioDate?'due-red':''}">${date(i.due)}</td></tr>`)):empty('No issues match this scope.');}
function documentTable(docs){return docs.length?table(['Document','Version','Updated','Owner',''],docs.map(d=>`<tr><td>${button(d.name,'document',d.id,'link')}</td><td>${badge(d.version)}</td><td>${date(d.updated)}</td><td>${esc(name(d.ownerId))}</td><td>${button('Open','document',d.id,'quiet','arrow')}</td></tr>`)):empty('No documents yet. Add the input brief, plan or a reference link.');}
function historyView(events){return events.length?`<div class="panel-body">${events.slice().reverse().map(x=>`<div class="activity"><strong>${esc(x.label)}</strong><br><span class="muted small">${esc(name(x.actorId))} · ${new Date(x.at).toLocaleString('en-GB')} · ${esc(x.entityId)}</span></div>`).join('')}</div>`:empty('Changes made in this local workspace will appear here.');}
function reportFilter(){return {projectIds:ui.reportProjectIds,programId:ui.reportProgram,department:ui.reportDepartment,health:ui.reportHealth};}
function renderReports(){const rows=reportRows(s,reportFilter()),ids=rows.map(x=>x.id),issues=s.issues.filter(i=>ids.includes(i.projectId)&&activeIssue(i));const counts=HEALTH.map(h=>({h,n:rows.filter(p=>p.health===h).length}));return header('Status Reports','Review one project, a portfolio slice or a department. Save a snapshot when ready.',button('Export CSV','export-report','','','download')+(editAllowed()?button('Save snapshot','save-report','','primary'):'') )+`<div class="toolbar">${button(ui.reportProjectIds.length?`${ui.reportProjectIds.length} projects selected`:'All projects','report-scope')}${filterSelect('reportProgram','All programs',s.programs.map(g=>[g.id,g.name]),ui.reportProgram)}${filterSelect('reportDepartment','All departments',depts(),ui.reportDepartment)}${filterSelect('reportHealth','All health',HEALTH,ui.reportHealth)}${button('Clear scope','clear-report','','quiet')}</div><div class="stats">${stat('Projects in scope',rows.length,ui.reportDepartment||'All departments')}${stat('On track',rows.filter(p=>p.health==='On Track').length,'Published project health','green')}${stat('At risk / delayed',rows.filter(p=>['At Risk','Delayed'].includes(p.health)).length,'Needs management attention','amber')}${stat('Open obstacles',issues.length,'Across scoped projects','red')}</div><div class="two-col"><div>${panel('Project status',projectTable(reportProjects(s,reportFilter())))}${panel('Latest updates',rows.length?`<div class="panel-body">${rows.map(p=>`<div class="activity">${button(p.name,'project',p.id,'link')}<p class="text-block">${esc(p.summary)}</p></div>`).join('')}</div>`:empty('No projects in this scope.'))}</div><div>${panel('Health distribution',`<div class="panel-body">${counts.map(({h,n})=>`<div class="row" style="margin-bottom:13px">${badge(h)}<span class="grow"></span><strong>${n}</strong></div>`).join('')}<div class="legend">Department filters select relevant projects; project totals include the whole project. Department-only task counts are in Departments.</div></div>`)}${panel('Saved snapshots',s.reports.length?`<div class="panel-body">${s.reports.slice().reverse().map(r=>`<div class="activity">${button(r.title,'report-snapshot',r.id,'link')}<br><span class="muted small">${r.rows.length} projects · ${new Date(r.createdAt).toLocaleDateString('en-GB')}</span></div>`).join('')}</div>`:empty('Save the current scope to keep a stable report.'))}</div></div>`;}
function renderSupport(){let issues=s.issues.filter(i=>(!ui.supportStatus||ui.supportStatus==='all'||ui.supportStatus==='open'&&activeIssue(i)||ui.supportStatus==='closed'&&!activeIssue(i))&&(!ui.department||i.department===ui.department)&&(!ui.severity||i.severity===ui.severity)&&(!ui.search||`${i.title} ${i.projectId} ${i.rootCause}`.toLowerCase().includes(ui.search.toLowerCase())));return header('Support & Knowledge','Resolve project obstacles. Keep what the next team can learn.',editAllowed()?button('Record issue','new-issue','','primary','plus'):'')+`<div class="stats">${stat('Open issues',s.issues.filter(activeIssue).length,'Across departments')}${stat('Critical / high',s.issues.filter(i=>activeIssue(i)&&['Critical','High'].includes(i.severity)).length,'Review the impact','red')}${stat('Open recovery actions',s.actions.filter(a=>!['Done','Cancelled'].includes(a.status)&&activeIssue(s.issues.find(i=>i.id===a.issueId))).length,'Individually owned','amber')}${stat('Reusable lessons',s.lessons.length,'Linked to resolved issues','green')}</div>`+tabs([['issues','Issue register'],['knowledge','Lessons learned']],ui.supportTab,'support-tab')+searchBar(ui.supportTab==='knowledge'?'Search lessons and prevention':'Search issue, project or root cause',filterSelect('department','All departments',depts(),ui.department)+(ui.supportTab==='issues'?filterSelect('supportStatus','Any status',[['all','All issues'],['open','Open issues'],['closed','Closed issues']],ui.supportStatus)+filterSelect('severity','All severities',['Critical','High','Medium','Low'],ui.severity):''))+(ui.supportTab==='issues'?panel('Project obstacles',issueTable(issues.sort((a,b)=>['Critical','High','Medium','Low'].indexOf(a.severity)-['Critical','High','Medium','Low'].indexOf(b.severity)))):renderLessons());}
function renderLessons(){const ls=s.lessons.filter(l=>(!ui.department||l.department===ui.department)&&(!ui.search||`${l.title} ${l.summary}`.toLowerCase().includes(ui.search.toLowerCase())));return `<div class="cards">${ls.map(l=>`<article class="lesson">${badge(l.department)}<h3 style="margin-top:12px">${esc(l.title)}</h3><p>${esc(l.summary)}</p><div class="small muted">Source: ${button(l.issueId,'issue',l.issueId,'link')} · Reused ${l.useCount} times</div><div class="row" style="margin-top:17px">${editAllowed()?button('Use in a project','reuse-lesson',l.id,'primary','plus'):''}</div></article>`).join('')}</div>`+(ls.length?'':empty('No lessons match. Resolve an issue and save its prevention advice as a lesson.'));}
function renderDepartment(){const ts=s.tasks.filter(t=>t.workstream===ui.dept),issues=s.issues.filter(i=>i.department===ui.dept),ps=s.projects.filter(p=>ts.some(t=>t.projectId===p.id)||issues.some(i=>i.projectId===p.id));const members=s.people.filter(p=>p.department===ui.dept||ts.some(t=>t.ownerIds.includes(p.id)));let body='';if(ui.deptTab==='overview')body=`<div class="two-col"><div>${panel('Department projects',projectTable(ps))}${panel('Assessments waiting for input',taskTable(ts.filter(t=>t.kind==='Assessment'&&!done(t)&&(!t.assessmentDecision||t.assessmentDecision==='Needs Information'))))}</div><div>${panel('Work distribution',`<div class="panel-body">${members.map(p=>{const all=ts.filter(t=>t.ownerIds.includes(p.id)),open=all.filter(t=>!done(t)).length;return `<div class="bar-row"><span>${esc(p.name)}</span><div class="progress"><span style="width:${all.length?open/all.length*100:0}%"></span></div><strong>${open}</strong></div>`;}).join('')}<p class="legend">Open assigned tasks, not hours or capacity utilization.</p></div>`)}${panel('Department obstacles',issueCards(issues.filter(activeIssue)))}</div></div>`;if(ui.deptTab==='assessments')body=panel('Department assessments',taskTable(ts.filter(t=>t.kind==='Assessment')));if(ui.deptTab==='tasks')body=panel('Department work',taskTable(ts));if(ui.deptTab==='issues')body=panel('Department issues',issueTable(issues));return header(ui.dept+' Department','Coordinate assessment inputs, assignments and the projects your team supports.',button('Department report','report-department',ui.dept,'','reports'))+`<div class="dept-list">${depts().map(d=>button(d,'department-pick',d,ui.dept===d?'active':'')).join('')}</div><div class="stats">${stat('Projects supported',ps.length,'Relevant work or issues')}${stat('Open tasks',ts.filter(t=>!done(t)).length,'This workstream')}${stat('Overdue tasks',ts.filter(t=>!done(t)&&t.due<s.scenarioDate).length,'Follow up with owners','red')}${stat('Open issues',issues.filter(activeIssue).length,'Department accountability','amber')}</div>`+tabs([['overview','Overview'],['assessments','Assessments'],['tasks','All work'],['issues','Issues']],ui.deptTab,'department-tab')+body;}
function formSubmit(handler){$('#detail-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const submit=$('button[form="detail-form"]');if(submit)submit.disabled=true;try{await handler(new FormData(e.target));}catch(err){errorAtForm(err.message);}finally{if(submit)submit.disabled=false;}};}
function openTask(id){return simple.openTask(id);}
function taskFormValues(f){const values=Object.fromEntries(['title','start','due','brief','outcome','kind','workstream','phase','priority','assessmentDecision','testResult','approvalStatus','approvalDate','durationBasis'].map(k=>[k,f.get(k)]));values.duration=Number(f.get('duration'));values.ownerIds=f.getAll('ownerIds');values.predecessorIds=f.getAll('predecessorIds');values.sourceAssessmentIds=f.getAll('sourceAssessmentIds');if(values.ownerIds.includes(ui.person))values.confirmOwnPart=f.has('confirmOwnPart');return values;}
function openNewTask(projectId='',sources=[]){return simple.openNewTask(projectId,sources);}
function openProjectEdit(id){const p=project(s,id);showDrawer('Edit project overview',`${p.id} · Shared across every center`,field('Project name','name',p.name)+`<div class="form-grid">${selectField('Project stage','stage',STAGES,p.stage)}${selectField('Project health','health',HEALTH,p.health)}${selectField('Project lead','leadId',s.people.map(x=>[x.id,x.name]),p.leadId)}${field('Factory','factory',p.factory)}${field('Target MP','targetMP',p.targetMP,'date')}${selectField('Priority','priority',['Normal','High','Low'],p.priority)}</div>`+field('Project scope / what is changing','scope',p.scope,'textarea')+field('Latest project update','summary',p.summary,'textarea')+checks('Project team','team',s.people.map(x=>[x.id,`${x.name} · ${x.department}`]),p.team),{save:'Save project'});formSubmit(async f=>{await operation('updateProject',id,{...Object.fromEntries(['name','stage','health','leadId','factory','targetMP','priority','scope','summary'].map(k=>[k,f.get(k)])),team:f.getAll('team')});closeDrawer();});}
function openNewProject(){showDrawer('Create a project','Start with the right team and assessment plan',`<div class="form-grid">${field('Project ID','id','')}${selectField('Program','programId',s.programs.map(g=>[g.id,g.name]),s.programs[0].id)}</div>`+field('Project name','name','')+`<div class="form-grid">${selectField('Type','type',['Extension','New CMF','NPD','Dual Source'],'Extension')}${selectField('Project lead','leadId',s.people.map(p=>[p.id,p.name]),ui.person)}${field('Factory','factory','')}${field('Target MP','targetMP','','date')}</div>`+field('SKU names, separated by commas','skuNames','')+field('What is changing','scope','','textarea')+`<label class="row small"><input type="checkbox" name="applyTemplate" checked> Create the cross-functional assessment plan</label><div class="notice" style="margin-top:15px">Creates 11 assessment tasks. Dates are initial placeholders for the team to review; this does not issue an ECN approval.</div>`,{save:'Create project'});formSubmit(async f=>{const r=await operation('createProject','',{...Object.fromEntries(['id','programId','name','type','leadId','factory','targetMP','skuNames','scope'].map(k=>[k,f.get(k)])),applyTemplate:f.has('applyTemplate')});closeDrawer();goProject(r.id);});}
function openIssue(id){const i=s.issues.find(x=>x.id===id);if(!i)return;const acts=s.actions.filter(a=>a.issueId===id);showDrawer(i.title,`${i.id} · ${i.projectId} · ${pName(i.projectId)}`,`<div class="row wrap" style="margin-bottom:15px">${badge(i.status)}${badge(i.severity)}${i.impactMP?badge('MP impact'):''}${simple.issueButtons(i)}${editAllowed()?button('Edit details','edit-issue',id,'quiet'):''}</div><h3>What happened</h3><p class="text-block" style="margin:10px 0 18px">${esc(i.details)}</p><div class="detail-grid"><div class="datum"><label>Accountable lead</label><p>${esc(name(i.ownerId))}</p></div><div class="datum"><label>Department</label><p>${esc(i.department)}</p></div><div class="datum"><label>Target resolution</label><p>${date(i.due)}</p></div></div><h3 class="section-title">Impact & affected work</h3><p class="text-block">${esc(i.impact||'Impact is not yet assessed.')}</p><div class="row wrap" style="margin-top:10px">${i.relatedTaskIds.map(t=>button(s.tasks.find(x=>x.id===t)?.title||t,'task',t,'link')).join(' · ')}</div><p class="small muted" style="margin-top:10px">Affected SKUs: ${i.affectedProjectSkuIds.length?i.affectedProjectSkuIds.map(x=>{const ps=s.projectSkus.find(y=>y.id===x);return esc(s.skus.find(z=>z.id===ps.skuId).name);}).join(', '):'Not assessed — not assumed to affect all SKUs'}</p><h3 class="section-title">Recovery actions <span class="muted small">${acts.filter(a=>a.status==='Done').length} / ${acts.length} done</span></h3>${acts.map(a=>`<div class="action-card"><div class="row">${badge(a.status)}<span class="grow"></span>${editAllowed()&&i.status!=='Closed'?button('Update','action',a.id):''}</div><p><strong>${esc(a.title)}</strong></p><span class="small muted">${esc(name(a.ownerId))} · ${date(a.due)}</span>${a.result?`<p class="text-block">${esc(a.result)}</p>`:''}</div>`).join('')}${!acts.length?empty('No recovery actions recorded yet.'):''}${editAllowed()&&i.status!=='Closed'?`<div style="margin-top:12px">${button('Add recovery action','new-action',id,'','plus')}</div>`:''}<h3 class="section-title">Resolution & learning</h3><div class="datum"><label>Root cause</label><p class="text-block">${esc(i.rootCause||'Still under investigation')}</p></div><div class="datum" style="margin-top:15px"><label>Actual resolution</label><p class="text-block">${esc(i.resolution||'Not resolved yet')}</p></div>${i.closedDate?`<p class="small muted" style="margin-top:12px">Closed ${date(i.closedDate)}${i.closedBy?' · '+esc(name(i.closedBy)):''}</p>`:''}${i.returnReason?`<div class="notice">Follow-up needed: ${esc(i.returnReason)}</div>`:''}${i.prevention?`<div class="notice" style="margin-top:15px">${esc(i.prevention)}</div>`:''}${editAllowed()&&i.status==='Closed'?`<div class="row" style="margin-top:15px">${button('Save as a lesson','save-lesson',id,'primary')}${button('Reopen issue','reopen-issue',id)}</div>`:''}<h3 class="section-title">Activity</h3>${historyView(s.history.filter(x=>x.entityId===id||x.entity==='action'&&acts.some(a=>a.id===x.entityId)))}`,{wide:true});}
function openIssueForm(id='',pid=''){const i=id?s.issues.find(x=>x.id===id):null;const pId=i?.projectId||pid||ui.projectId||s.projects[0].id;showDrawer(i?'Edit issue':'Record an obstacle',i?`${i.id} · ${pId}`:'Issues are unexpected obstacles, separate from planned tasks',(!i?selectField('Project','projectId',s.projects.map(p=>[p.id,`${p.id} · ${p.name}`]),pId):'')+field('Short issue title','title',i?.title||'')+field('What happened','details',i?.details||'','textarea')+`<div class="form-grid">${selectField('Accountable lead','ownerId',s.people.map(p=>[p.id,p.name]),i?.ownerId||ui.person)}${selectField('Department','department',depts(),i?.department||person(s,ui.person).department)}${selectField('Severity','severity',['Critical','High','Medium','Low'],i?.severity||'Medium')}${field('Target resolution date','due',i?.due||'2026-09-18','date')}${selectField('Occurrence phase','phase',STAGES,i?.phase||project(s,pId).stage)}${selectField('Category','category',['Technical','Input / Documentation','Supplier / Resource','Process'],i?.category||'Technical')}</div>`+field('Impact on the project','impact',i?.impact||'','textarea')+`<label class="row small" style="margin-bottom:18px"><input type="checkbox" name="impactMP" ${i?.impactMP?'checked':''}> Impacts the MP plan</label><div id="issue-scope-fields">${issueScopeFields(pId,i)}</div><h3 class="section-title">Fill these as the issue is resolved</h3>`+field('Root cause','rootCause',i?.rootCause||'','textarea')+field('Actual resolution','resolution',i?.resolution||'','textarea')+field('How to prevent recurrence','prevention',i?.prevention||'','textarea'),{save:i?'Save issue':'Create issue'});formSubmit(async f=>{const vals={...Object.fromEntries(['title','details','ownerId','department','severity','due','phase','category','impact','rootCause','resolution','prevention'].map(k=>[k,f.get(k)])),projectId:i?.projectId||f.get('projectId'),impactMP:f.has('impactMP'),affectedProjectSkuIds:f.getAll('affectedProjectSkuIds'),relatedTaskIds:f.getAll('relatedTaskIds')};const r=await operation(i?'updateIssue':'createIssue',id,vals);closeDrawer();openIssue(r.id);});}
function issueScopeFields(pid,i){return checks('Affected SKUs (leave blank if not assessed)','affectedProjectSkuIds',s.projectSkus.filter(x=>x.projectId===pid).map(ps=>[ps.id,s.skus.find(x=>x.id===ps.skuId).name]),i?.affectedProjectSkuIds||[])+checks('Related tasks (optional)','relatedTaskIds',tasksFor(s,pid).map(t=>[t.id,t.title]),i?.relatedTaskIds||[]);}
function openAction(id='',issueId=''){const a=s.actions.find(x=>x.id===id),iid=a?.issueId||issueId,issue=s.issues.find(i=>i.id===iid);showDrawer(a?'Update recovery action':'Add recovery action',`${iid} · ${issue.title}`,field('What will be done','title',a?.title||'','textarea')+`<div class="form-grid">${selectField('Owner','ownerId',s.people.map(x=>[x.id,x.name]),a?.ownerId||ui.person)}${field('Due date','due',a?.due||'2026-09-18','date')}${selectField('Status','status',['Open','In Progress','Done','Cancelled'],a?.status||'Open')}</div>`+field('Actual result','result',a?.result||'','textarea')+field('Evidence link','evidenceUrl',a?.evidenceUrl||'','url')+`<div class="notice">This is an issue recovery action. It does not automatically become a task in the project plan.</div>`,{save:'Save action'});formSubmit(async f=>{await operation(a?'updateAction':'createAction',id,{issueId:iid,...Object.fromEntries(['title','ownerId','due','status','result','evidenceUrl'].map(k=>[k,f.get(k)]))});closeDrawer();openIssue(iid);});}
function openSku(id){const ps=s.projectSkus.find(x=>x.id===id),sku=s.skus.find(x=>x.id===ps.skuId),p=project(s,ps.projectId);showDrawer(sku.name,`${p.id} · ${p.name}`,`<div class="detail-grid"><div class="datum"><label>Market</label><p>${esc(sku.market)}</p></div><div class="datum"><label>Factory from project</label><p>${esc(p.factory)}</p></div></div><h3 class="section-title">Execution in this project</h3>`+selectField('SKU status','status',['In Development','At Risk','Blocked','In MP'],ps.status)+`<div class="notice">Project target MP: ${date(p.targetMP)}. With no exception, this SKU follows that target.</div><div style="margin-top:17px">`+field('SKU MP date exception (optional)','overrideDate',ps.overrideDate,'date')+field('Why this SKU needs another date','overrideReason',ps.overrideReason,'textarea')+`</div><h3 class="section-title">Issues affecting this SKU</h3>${issueCards(s.issues.filter(i=>i.affectedProjectSkuIds.includes(id)&&activeIssue(i)))}<h3 class="section-title">Other projects using this SKU</h3>${skuTable(s.projectSkus.filter(x=>x.skuId===sku.id&&x.id!==id))}`,{save:'Save SKU execution'});formSubmit(async f=>{await operation('updateSku',id,Object.fromEntries(['status','overrideDate','overrideReason'].map(k=>[k,f.get(k)])));closeDrawer();});}
function openDocument(id){const d=s.documents.find(x=>x.id===id);if(!d)return;showDrawer(d.name,`${d.projectId} · ${d.version} · ${date(d.updated)}`,`<div class="row" style="margin-bottom:18px">${button('Download copy','download-document',id,'','download')}${d.url?`<a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}</div><pre class="document-content">${esc(d.content||'Reference link: '+d.url)}</pre>`);}
function openDocumentForm(pid){showDrawer('Add a project reference',`${pid} · Documents`,field('Document name','name','')+`<div class="form-grid">${field('Version','version','v1')}${field('Reference URL (optional)','url','','url')}</div>`+field('Notes or document content','content','','textarea'),{save:'Add document'});formSubmit(async f=>{const r=await operation('createDocument','',{projectId:pid,...Object.fromEntries(['name','version','url','content'].map(k=>[k,f.get(k)]))});closeDrawer();openDocument(r.id);});}
function openReportScope(){showDrawer('Choose projects','Leave all unchecked to include every project',checks('Projects','projectIds',s.projects.map(p=>[p.id,`${p.id} · ${p.name}`]),ui.reportProjectIds),{save:'Apply scope'});if(!editAllowed()){$('#detail-form').querySelectorAll('input').forEach(e=>e.disabled=false);$('.drawer-foot').insertAdjacentHTML('beforeend','<button type="submit" form="detail-form" class="primary">Apply scope</button>');}formSubmit(async f=>{ui.reportProjectIds=f.getAll('projectIds');closeDrawer();render();});}
async function download(name,content){const response=await fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,content})});const file=await response.json();if(!response.ok)throw new Error(file.error||'Unable to prepare the file.');showDrawer('Your file is ready',file.name,`<p class="text-block">A copy is saved in your local workspace. You can open it or download a copy.</p><div class="row wrap" style="margin-top:20px"><a href="${esc(file.url)}" download="${esc(file.name)}">Download copy</a><a href="${esc(file.url)}?preview=1" target="_blank" rel="noopener">Open file</a></div>`);return file;}
async function exportRows(rows,name='AutoPM-project-status.csv'){const cols=['id','name','program','stage','health','lead','factory','targetMP','done','total','overdue','openIssues','summary'];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';await download(name,'\uFEFF'+[cols.map(cell).join(','),...rows.map(r=>cols.map(c=>cell(r[c])).join(','))].join('\r\n'));}
function openReportSnapshot(id){const r=s.reports.find(x=>x.id===id);showDrawer(r.title,`${r.rows.length} projects · Saved ${new Date(r.createdAt).toLocaleString('en-GB')}`,`<div class="notice">This is a saved snapshot. Later project edits do not change these values.</div><div style="margin:15px 0">${button('Export this snapshot','export-snapshot',id,'','download')}</div>`+table(['Project','Stage','Health','Open issues'],r.rows.map(p=>`<tr><td>${esc(p.name)}<span class="sub">${esc(p.id)}</span></td><td>${esc(p.stage)}</td><td>${badge(p.health)}</td><td>${p.openIssues}</td></tr>`)),{wide:true});}
function openLessonForm(issueId){const i=s.issues.find(i=>i.id===issueId);showDrawer('Save a reusable lesson',`${issueId} · ${i.department}`,field('Lesson title','title',i.title)+field('What should the next project do differently?','summary',i.prevention||'','textarea')+`<div class="notice">The lesson links back to this issue, its resolution and recovery actions.</div>`,{save:'Save lesson'});formSubmit(async f=>{await operation('saveLesson','',{issueId,title:f.get('title'),summary:f.get('summary')});closeDrawer();ui.page='support';ui.supportTab='knowledge';ui.search='';ui.department='';render();});}
function openReuseLesson(id){const l=s.lessons.find(x=>x.id===id);showDrawer('Use this lesson in a project',l.title,`<p class="text-block" style="margin-bottom:18px">${esc(l.summary)}</p>`+selectField('Project','projectId',s.projects.map(p=>[p.id,`${p.id} · ${p.name}`]),s.projects[0].id)+`<div class="notice">Creates a planned prevention task for the project lead. The original issue and lesson remain unchanged.</div>`,{save:'Add to project plan'});formSubmit(async f=>{const r=await operation('reuseLesson',id,{projectId:f.get('projectId')});closeDrawer();openTask(r.id);});}
function goProject(id){ui.page='projects';ui.projectId=id;ui.projectTab='overview';ui.search='';ui.taskKind='';closeDrawer();render();window.scrollTo(0,0);}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target)return;const {action,id}=target.dataset;if(action==='backdrop'&&e.target!==target)return;try{if(action==='nav'){ui.page=id;ui.search='';ui.projectId='';ui.programId='';document.body.classList.remove('menu-open');closeDrawer();render();}else if(action==='menu')document.body.classList.toggle('menu-open');else if(action==='close'||action==='backdrop')closeDrawer();else if(action==='personal-tab'){ui.personalTab=id;ui.workLimit=10;render();}else if(action==='task')openTask(id);else if(action==='confirm-task')await operation('confirmTask',id);else await handleAction(action,id,target);}catch(err){errorAtForm(err.message);}});
document.addEventListener('change',e=>{if(e.target.id==='person-select'){ui.person=e.target.value;localStorage.setItem('autopm-person',ui.person);render();}if(e.target.id==='role-select'){ui.mode=e.target.value;localStorage.setItem('autopm-mode',ui.mode);closeDrawer();render();}handleChange(e);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Tab'&&currentDrawer){const els=[...$('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}});
async function handleAction(action,id,target){
 const handled=simple.handleAction(action,id);if(handled){await handled;return;}
 if(action==='more-table'){const record=tableRows.get(target.dataset.table);if(!record)return;const n=record.shown;target.closest('.table-wrap').querySelector('tbody').insertAdjacentHTML('beforeend',record.rows.slice(n,n+50).join(''));record.shown+=50;if(record.shown>=record.rows.length)target.parentElement.remove();else target.nextElementSibling.textContent=record.shown+' of '+record.rows.length;return;}
 if(action==='project')goProject(id);
 else if(action==='projects-back'){ui.projectId='';ui.search='';render();}
 else if(action==='project-tab'){ui.projectTab=id;ui.search='';render();}
 else if(action==='new-project')openNewProject();
 else if(action==='edit-project')openProjectEdit(id);
 else if(action==='new-task')openNewTask(id);
 else if(action==='follow-up'){if(saving)return;await operation('updateTask',id,taskFormValues(new FormData($('#detail-form'))));const t=s.tasks.find(x=>x.id===id);openNewTask(t.projectId,[id]);}
 else if(action==='reload-workspace'){const response=await fetch('/api/state');if(!response.ok)throw new Error('Unable to load the latest workspace.');s=await response.json();closeDrawer();render();toast('Latest data loaded. Reopen the record to review and edit.');}
 else if(action==='confirm-in-drawer'){await operation('confirmTask',id);openTask(id);}
 else if(action==='issue')openIssue(id);
 else if(action==='new-issue')openIssueForm('',id);
 else if(action==='edit-issue')openIssueForm(id);
 else if(action==='action')simple.openAction(id);
 else if(action==='new-action')openAction('',id);
 else if(action==='reopen-issue'){await operation('updateIssue',id,{status:'In Recovery'});openIssue(id);}
 else if(action==='sku')openSku(id);
 else if(action==='program'){ui.page='portfolio';ui.programId=id;ui.search='';closeDrawer();render();window.scrollTo(0,0);}
 else if(action==='programs-back'){ui.programId='';render();}
 else if(action==='clear-project-filters'){ui.search='';ui.health='';ui.stage='';render();}
 else if(action==='document')openDocument(id);
 else if(action==='download-document'){const d=s.documents.find(x=>x.id===id);await download(d.name.replace(/[^a-z0-9-]/gi,'_')+'.txt',d.content||d.url);}
 else if(action==='new-document')openDocumentForm(id);
 else if(action==='support-tab'){ui.supportTab=id;ui.search='';render();}
 else if(action==='save-lesson')openLessonForm(id);
 else if(action==='reuse-lesson')openReuseLesson(id);
 else if(action==='report-scope')openReportScope();
 else if(action==='report-project'){ui.page='reports';ui.reportProjectIds=[id];ui.reportProgram='';ui.reportDepartment='';ui.reportHealth='';closeDrawer();render();}
 else if(action==='report-department'){ui.page='reports';ui.reportProjectIds=[];ui.reportProgram='';ui.reportDepartment=id;ui.reportHealth='';render();}
 else if(action==='clear-report'){ui.reportProjectIds=[];ui.reportProgram='';ui.reportDepartment='';ui.reportHealth='';render();}
 else if(action==='export-report')await exportRows(reportRows(s,reportFilter()));
 else if(action==='save-report'){showDrawer('Save status snapshot','Preserve the report as it looks now',field('Report title','title',`${ui.reportDepartment||'Project'} status · 14 Sep 2026`)+`<div class="notice">${reportRows(s,reportFilter()).length} projects. Later edits will not change this snapshot.</div>`,{save:'Save snapshot'});formSubmit(async f=>{const r=await operation('saveReport','',{title:f.get('title'),filter:reportFilter()});closeDrawer();openReportSnapshot(r.id);});}
 else if(action==='report-snapshot')openReportSnapshot(id);
 else if(action==='export-snapshot'){const r=s.reports.find(x=>x.id===id);await exportRows(r.rows,'AutoPM-snapshot.csv');}
 else if(action==='department-pick'){ui.dept=id;render();}
 else if(action==='department-tab'){ui.deptTab=id;render();}
 else if(action==='guide')openGuide();
}
function handleChange(e){const el=e.target;if(el.dataset.filter){const allowed=['stage','health','brand','taskKind','reportProgram','reportDepartment','reportHealth','department','supportStatus','severity'];if(allowed.includes(el.dataset.filter)){ui[el.dataset.filter]=el.value;render();}}if(el.id==='f-kind')$('#detail-form')?.querySelectorAll('[data-kind]').forEach(x=>x.classList.toggle('hide',x.dataset.kind!==el.value));if(el.id==='f-projectId'&&$('#issue-scope-fields'))$('#issue-scope-fields').innerHTML=issueScopeFields(el.value,null);}
document.addEventListener('input',e=>{if(e.target.id!=='workspace-search')return;const start=e.target.selectionStart;ui.search=e.target.value;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>{render();const input=$('#workspace-search');input?.focus();input?.setSelectionRange(start,start);},160);});
function openLegacyGuide(){showDrawer('Try the complete AutoPM workflow','Start with a person, then follow the same records across centers',`<div class="text-block"><strong>1. My Work</strong><br>Choose Sun Sun or another person at the top. Open a task, read the brief, update its outcome or confirm your own part.<br><br><strong>2. Project Center</strong><br>Open a project to see its overview, assessment and execution plan, SKUs, issues, team and documents. From an assessment, create a separate follow-up task.<br><br><strong>3. Portfolio</strong><br>Open a Program, then a Project or SKU. SKU execution and exceptions belong to a specific project.<br><br><strong>4. Status Reports</strong><br>Select one or several projects, a Program or a department. Export the scope, or save a snapshot for later.<br><br><strong>5. Support & Knowledge</strong><br>Record an obstacle, assign individual recovery actions and capture the resolution. Save a lesson, then use it to create a prevention task in another project.<br><br><strong>6. Departments</strong><br>Choose a department to see its assessments, assigned work, project coverage and open issues.<br><br><strong>Working modes</strong><br>Contributor and Maintainer can edit this local sandbox. Viewer can browse, filter and export. Person switching and modes demonstrate the experience; they are not company authentication or production permissions.</div><h3 class="section-title">Data and field adjustments</h3><p class="text-block">Project, Task and Issue remain separate. This version adds work briefs, assessment decisions, test and external approval results, actual plan dependencies, source assessments and individual issue actions. Existing owner confirmation remains separate from technical results.</p><h3 class="section-title">What is real in this prototype</h3><div class="notice">${esc(s.sourceNote)}</div><p class="text-block" style="margin-top:15px">Saved changes are kept in this local website's data file. No changes are sent to Airtable, ECN or Microsoft. Sample documents are clearly marked and can be opened and downloaded.</p>`);}
function openGuide(){showDrawer('Using My Work','Your daily work, in one place',`<div class="text-block"><strong>1. Open your work</strong><br>Needs attention brings forward overdue and due tasks. All open includes upcoming work. Search by task or project.<br><br><strong>2. Save an update</strong><br>Open a task, record the latest result and check My part is complete when ready. The project and department use this same record.<br><br><strong>3. Resolve an issue</strong><br>Update your recovery action. The issue lead submits the resolution; the project lead confirms closure.<br><br><strong>4. Add work</strong><br>Choose an active project, name the task and set the due date. Owners and planning details are prefilled where the project provides them.</div>`);}
function registerAgentTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const controller=new AbortController();const tools=[{name:'autopm_list_current_work',title:'List current person’s work',description:'Read the selected person’s open project tasks and recovery actions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({person:ui.person,tasks:s.tasks.filter(t=>t.ownerIds.includes(ui.person)&&!done(t)).map(t=>({id:t.id,title:t.title,projectId:t.projectId,due:t.due})),actions:s.actions.filter(a=>a.ownerId===ui.person&&!['Done','Cancelled'].includes(a.status)).map(a=>({id:a.id,title:a.title,issueId:a.issueId}))})},{name:'autopm_open_project',title:'Open a project',description:'Navigate to the existing project detail. Does not modify project data.',inputSchema:{type:'object',properties:{projectId:{type:'string'}},required:['projectId'],additionalProperties:false},annotations:{readOnlyHint:true},execute:({projectId})=>{if(!project(s,projectId))throw new Error('Unknown project');goProject(projectId);return {opened:projectId};}},{name:'autopm_update_task_outcome',title:'Save a task outcome',description:'Save the actual outcome to an existing task in the local workspace. Uses the same validation and working mode as the form.',inputSchema:{type:'object',properties:{taskId:{type:'string'},outcome:{type:'string'}},required:['taskId','outcome'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({taskId,outcome})=>{if(typeof outcome!=='string'||!s.tasks.some(t=>t.id===taskId))throw new Error('Provide an existing task ID and outcome text.');const r=await operation('updateTask',taskId,{outcome});openTask(r.id);return {saved:true,taskId:r.id,revision:s.revision};}}];for(const tool of tools){const execute=tool.execute;tool.execute=(input)=>{const props=tool.inputSchema.properties;if(!input||Array.isArray(input)||typeof input!=='object'||Object.keys(input).some(k=>!Object.hasOwn(props,k))||(tool.inputSchema.required||[]).some(k=>!Object.hasOwn(input,k))||Object.entries(input).some(([k,v])=>typeof v!==props[k].type))throw new Error('Invalid tool input. Use only the fields defined for this action.');return execute(input);};try{Promise.resolve(ctx.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
async function start(){try{const response=await fetch('/api/state');if(!response.ok)throw new Error('The local workspace could not be loaded.');s=await response.json();if(!person(s,ui.person))ui.person=s.people[0].id;render();registerAgentTools();}catch(e){$('#app').innerHTML=`<main class="loading"><h1>Workspace unavailable</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Try again</button></main>`;}}
const simple=createSimpleUI({getState:()=>s,ui,esc,button,badge,field,selectField,showDrawer,closeDrawer,formSubmit,operation,render,header,panel,tabs,stat,empty,date,historyView,editAllowed,openIssue});
document.addEventListener('input',e=>{simple.handleInput(e);if(e.target.classList.contains('check-search')){const query=e.target.value.toLowerCase();e.target.parentElement.querySelectorAll('label').forEach(l=>l.hidden=!l.textContent.toLowerCase().includes(query));}});
start();
